=== FILE: deep_counter_props.sv ===
// Formal properties for deep_counter, written from interface_spec.md.
// Immediate assertions only (open Yosys front end); no assumptions: all
// inputs are free. Requirement tags refer to interface_spec.md section 3.

module deep_counter_props #(
    parameter integer LIMIT = 99
) (
    input wire       clk,
    input wire       rst_n,
    input wire       en,
    input wire       clr,
    input wire [6:0] count,
    input wire       carry
);
    localparam [6:0] F_LAST = LIMIT;

    // First-cycle guard for $past.
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk)
        f_past_valid <= 1'b1;

    // Set once a reset has been applied at a rising edge.
    reg f_rst_seen;
    initial f_rst_seen = 1'b0;
    always @(posedge clk)
        if (!rst_n)
            f_rst_seen <= 1'b1;

    // [req:DC-CARRY] carry follows inputs and count combinationally.
    always @(*)
        assert (carry == (en && !clr && (count == F_LAST)));

    // [req:DC-RANGE] count never above LIMIT once reset has been seen.
    always @(*)
        if (f_rst_seen)
            assert (count <= F_LAST);

    always @(posedge clk) begin
        if (f_past_valid) begin
            // [req:DC-RESET]
            if (!$past(rst_n))
                assert (count == 7'd0);
            // [req:DC-CLEAR] clear wins over enable
            if ($past(rst_n) && $past(clr))
                assert (count == 7'd0);
            // [req:DC-COUNT] increment below LIMIT
            if ($past(rst_n) && !$past(clr) && $past(en) && ($past(count) < F_LAST))
                assert (count == ($past(count) + 7'd1));
            // [req:DC-COUNT] wrap at LIMIT
            if ($past(rst_n) && !$past(clr) && $past(en) && ($past(count) == F_LAST))
                assert (count == 7'd0);
            // [req:DC-HOLD]
            if ($past(rst_n) && !$past(clr) && !$past(en))
                assert (count == $past(count));
        end
    end

    // Covers: scenarios the proof must still allow, all after a reset.
    always @(posedge clk) begin
        if (f_past_valid && f_rst_seen) begin
            cover (count == F_LAST);
            cover (carry);
            cover ($past(carry) && $past(rst_n) && (count == 7'd0));
            cover ($past(rst_n) && $past(clr) && $past(en) && ($past(count) != 7'd0));
            cover (en && clr && (count == F_LAST));
            cover ($past(rst_n) && !$past(clr) && !$past(en) && (count != 7'd0));
        end
    end
endmodule

// Formal top: the approved RTL at its default LIMIT, plus the edge values
// LIMIT = 1 and LIMIT = 127, each with independent free inputs.
module deep_counter_formal (
    input wire clk,
    input wire rst_n_d, en_d, clr_d,
    input wire rst_n_1, en_1, clr_1,
    input wire rst_n_m, en_m, clr_m
);
    wire [6:0] count_d, count_1, count_m;
    wire       carry_d, carry_1, carry_m;

    deep_counter u_dut_default (
        .clk(clk), .rst_n(rst_n_d), .en(en_d), .clr(clr_d),
        .count(count_d), .carry(carry_d)
    );
    deep_counter_props #(.LIMIT(99)) u_props_default (
        .clk(clk), .rst_n(rst_n_d), .en(en_d), .clr(clr_d),
        .count(count_d), .carry(carry_d)
    );

    deep_counter #(.LIMIT(1)) u_dut_min (
        .clk(clk), .rst_n(rst_n_1), .en(en_1), .clr(clr_1),
        .count(count_1), .carry(carry_1)
    );
    deep_counter_props #(.LIMIT(1)) u_props_min (
        .clk(clk), .rst_n(rst_n_1), .en(en_1), .clr(clr_1),
        .count(count_1), .carry(carry_1)
    );

    deep_counter #(.LIMIT(127)) u_dut_max (
        .clk(clk), .rst_n(rst_n_m), .en(en_m), .clr(clr_m),
        .count(count_m), .carry(carry_m)
    );
    deep_counter_props #(.LIMIT(127)) u_props_max (
        .clk(clk), .rst_n(rst_n_m), .en(en_m), .clr(clr_m),
        .count(count_m), .carry(carry_m)
    );
endmodule
